package com.greenocean.backend.listener.planning;
import com.greenocean.backend.listener.live.*;
import jakarta.validation.constraints.*;
import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;
import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;

@Service @Transactional(noRollbackFor=LiveSupportException.class)
public class ListenerQueue {
 private final ListenerSupportPolicy p;private final LiveSupportService live;
 public ListenerQueue(ListenerSupportPolicy p,LiveSupportService live){this.p=p;this.live=live;}
 public record Admission(@NotNull UUID clientKey,@Size(max=40)String language,boolean reminders){}
 public record Confirmation(@NotNull UUID allocationId){}
 private Map<String,Object> owned(UUID id,UUID member){var rows=p.db.queryForList("SELECT * FROM listener_wait_queue WHERE id=? AND member_id=?",id,member);if(rows.isEmpty())throw denied(404,"QUEUE_NOT_FOUND","Queue entry was not found.");return rows.getFirst();}
 public Map<String,Object> view(UUID id,UUID member){var q=owned(id,member);var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","status","admitted_at","expires_at","allocation_id","allocation_expires_at","reason_code","live_request_id","revision"))out.put(key,q.get(key));out.put("ordinal",String.valueOf(q.get("sequence")));out.put("server_time",p.now());out.put("live_status",q.get("live_request_id")==null?null:p.db.queryForObject("SELECT status FROM live_support_requests WHERE id=?",String.class,q.get("live_request_id")));out.put("earlier_waiting_entries","WAITING".equals(q.get("status"))?p.db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE status='WAITING' AND sequence<?",Long.class,q.get("sequence")):null);if("OFFERED".equals(q.get("status")))out.put("listener_name",p.db.queryForObject("SELECT display_name FROM profiles WHERE user_id=?",String.class,q.get("listener_id")));return out;}
 public Map<String,Object> state(UUID member){work();p.eligible(member);var rows=p.db.queryForList("SELECT id FROM listener_wait_queue WHERE member_id=? ORDER BY sequence DESC LIMIT 1",UUID.class,member);return Map.of("enabled",p.queue(),"coverageAvailable",p.queue()&&p.truth("SELECT listener_queue_has_coverage(?,NULL)",member),"serverTime",p.now(),"entry",rows.isEmpty()?Map.of():view(rows.getFirst(),member));}
 public Map<String,Object> get(UUID id,UUID member){work();p.eligible(member);return view(id,member);}
 public Map<String,Object> join(UUID member,Admission input){p.liveLock();live.reconcile();p.require("QUEUE");p.eligible(member);String language=input.language()==null||input.language().isBlank()?null:input.language().trim();
  var retry=p.db.queryForList("SELECT id,language,reminders FROM listener_wait_queue WHERE member_id=? AND client_key=?",member,input.clientKey());if(!retry.isEmpty()){var q=retry.getFirst();if(!Objects.equals(language,q.get("language"))||input.reminders()!=(Boolean)q.get("reminders"))throw denied(409,"IDEMPOTENCY_CONFLICT","This retry key belongs to another queue choice.");return view((UUID)q.get("id"),member);}
  p.bound(member,"QUEUE_JOIN",10);
  if(p.truth("SELECT EXISTS(SELECT 1 FROM listener_wait_queue WHERE member_id=? AND status IN('WAITING','OFFERED'))",member))throw denied(409,"QUEUE_ALREADY_OPEN","You already have an active waiting entry. Review or cancel it first.");
  if(!p.truth("SELECT listener_all_capacity_available(?,?,NULL,NULL)",member,member))throw denied(409,"COMMITMENT_CONFLICT","An existing support allocation conflicts with a new waiting attempt.");
  var limits=p.limits();if(!p.truth("SELECT listener_booking_free(?,?,listener_support_now(),listener_support_now()+(?*INTERVAL '1 second'),NULL)",member,member,limits.queueSeconds()+limits.plannedSeconds()+limits.handoffSeconds()+limits.bufferSeconds()))throw denied(409,"COMMITMENT_CONFLICT","An existing commitment prevents a bounded waiting attempt. Review Live Now or your bookings.");
  if(p.db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE status IN('WAITING','OFFERED')",Integer.class)>=limits.queueCapacity())throw denied(409,"QUEUE_FULL","The bounded waiting queue is full. No entry was created.");
  if(!p.truth("SELECT listener_queue_has_coverage(?,?)",member,language))throw denied(409,"NO_QUEUE_COVERAGE","No currently staffed, qualified listener coverage supports this waiting attempt. No entry was created.");
  UUID id=UUID.randomUUID();p.db.update("INSERT INTO listener_wait_queue(id,member_id,client_key,language,reminders,expires_at) VALUES(?,?,?,?,?,listener_support_now())",id,member,input.clientKey(),language,input.reminders());p.notice(member,id,"QUEUE_ADMITTED",input.reminders());return view(id,member);
 }
 public Map<String,Object> cancel(UUID id,UUID member){p.liveLock();live.reconcile();var q=owned(id,member);String status=(String)q.get("status");if("TRANSFERRED".equals(status)){var request=live.get((UUID)q.get("live_request_id"),member);if(Set.of("REQUESTED","ACCEPTED").contains(request.status()))live.cancel(request.id(),member);else if(Set.of("ACTIVE","INTERRUPTED").contains(request.status()))throw denied(409,"LIVE_SESSION_ACTIVE","Use the live conversation end control for this transferred session.");return view(id,member);}if(Set.of("WAITING","OFFERED").contains(status)){p.db.update("UPDATE listener_wait_queue SET status='CANCELLED',reason_code='MEMBER_CANCELLED' WHERE id=?",id);p.notice(member,id,"QUEUE_CANCELLED",(Boolean)q.get("reminders"));}return view(id,member);}
 public Map<String,Object> confirm(UUID id,UUID member,Confirmation in){p.liveLock();live.reconcile();p.require("QUEUE");p.eligible(member);var q=owned(id,member);if(!Objects.equals(q.get("allocation_id"),in.allocationId()))throw denied(409,"MATCH_CHANGED","This readiness confirmation belongs to another proposal.");if("TRANSFERRED".equals(q.get("status")))return Map.of("entry",view(id,member),"request",live.get((UUID)q.get("live_request_id"),member));if(!"OFFERED".equals(q.get("status")))throw denied(409,"MATCH_EXPIRED","This match is no longer available. No new live request was created.");p.lock(member,(UUID)q.get("listener_id"));p.listener((UUID)q.get("listener_id"));if(!p.truth("SELECT live_listener_ready(?)",q.get("listener_id")))throw denied(409,"LISTENER_NOT_READY","The listener is not currently ready. No live request was created.");var request=live.createQueued(member,(UUID)q.get("allocation_id"),(UUID)q.get("listener_id"),id);p.db.update("UPDATE listener_wait_queue SET status='TRANSFERRED',live_request_id=?,reason_code='MEMBER_CONFIRMED' WHERE id=?",request.id(),id);return Map.of("entry",view(id,member),"request",request);}
 @Scheduled(fixedDelayString="${greenocean.listener-support.queue-sweep-ms:5000}") public void sweep(){work();}
 public void work(){p.liveLock();live.reconcile();if(!p.queue())return;p.require("QUEUE");
  for(var q:p.db.queryForList("SELECT * FROM listener_wait_queue WHERE status='WAITING' ORDER BY sequence LIMIT 500 FOR UPDATE SKIP LOCKED")){
   UUID member=(UUID)q.get("member_id"),id=(UUID)q.get("id");
   if(!p.truth("SELECT listener_calendar_capacity_available(?,?,NULL)",member,member)){p.db.update("UPDATE listener_wait_queue SET status='SERVICE_UNAVAILABLE',reason_code='COMMITMENT_CHANGED' WHERE id=?",id);continue;}
   if(!p.truth("SELECT EXISTS(SELECT 1 FROM listener_profiles l CROSS JOIN listener_support_policy policy WHERE l.user_id<>? AND live_listener_qualified(l.user_id) AND NOT live_pair_blocked(?,l.user_id) AND(?::text IS NULL OR ?=ANY(l.languages)) AND NOT EXISTS(SELECT 1 FROM listener_wait_queue own WHERE own.member_id=l.user_id AND own.status IN('WAITING','OFFERED')) AND listener_queue_staffed(l.user_id,listener_support_now()+((policy.planned_seconds+policy.handoff_seconds+policy.buffer_seconds)*INTERVAL '1 second')))",member,member,q.get("language"),q.get("language"))){p.db.update("UPDATE listener_wait_queue SET status='SERVICE_UNAVAILABLE',reason_code='COVERAGE_UNAVAILABLE' WHERE id=?",id);continue;}
   var limits=p.limits();Instant deadline=Collections.min(List.of(instant(q.get("expires_at")),p.now().plusSeconds(limits.matchSeconds())));
   var listeners=p.db.queryForList("SELECT p.listener_id FROM listener_presence p JOIN listener_profiles l ON l.user_id=p.listener_id WHERE p.listener_id<>? AND live_listener_ready(p.listener_id) AND NOT live_pair_blocked(?,p.listener_id) AND(?::text IS NULL OR ?=ANY(l.languages)) AND listener_queue_staffed(p.listener_id,?::timestamptz+(?*INTERVAL '1 second')) AND listener_all_capacity_available(?,p.listener_id,NULL,?) AND listener_booking_free(?,p.listener_id,listener_support_now(),?::timestamptz+(?*INTERVAL '1 second'),NULL) ORDER BY p.last_assigned_at NULLS FIRST,p.listener_id LIMIT 1",UUID.class,member,member,q.get("language"),q.get("language"),date(deadline),limits.plannedSeconds()+limits.handoffSeconds()+limits.bufferSeconds(),member,id,member,date(deadline),limits.plannedSeconds()+limits.handoffSeconds()+limits.bufferSeconds());
   if(listeners.isEmpty())continue;UUID listener=listeners.getFirst();p.lock(member,listener);int changed=p.db.update("UPDATE listener_wait_queue SET status='OFFERED',listener_id=?,allocation_id=?,allocation_expires_at=? WHERE id=? AND status='WAITING' AND expires_at>listener_support_now()",listener,UUID.randomUUID(),date(deadline),id);if(changed!=1)continue;p.db.update("UPDATE listener_presence SET last_assigned_at=clock_timestamp() WHERE listener_id=?",listener);p.notice(member,id,"QUEUE_MATCH_AVAILABLE",(Boolean)q.get("reminders"));
  }
  for(var q:p.db.queryForList("SELECT q.id,q.member_id,q.status,q.reminders FROM listener_wait_queue q JOIN user_preferences pref ON pref.user_id=q.member_id CROSS JOIN listener_support_policy policy WHERE q.reminders AND pref.notify_messages AND q.status IN('EXPIRED','SERVICE_UNAVAILABLE','SAFETY_TERMINATED') AND q.updated_at>listener_support_now()-(policy.queue_seconds*INTERVAL '1 second') AND NOT EXISTS(SELECT 1 FROM listener_support_notices n WHERE n.user_id=q.member_id AND n.entity_id=q.id AND n.kind=q.status) ORDER BY q.updated_at,q.id LIMIT 100"))p.notice((UUID)q.get("member_id"),(UUID)q.get("id"),(String)q.get("status"),(Boolean)q.get("reminders"));
  p.db.update("INSERT INTO listener_support_worker_state(name,last_success_at) VALUES('queue-reconciliation',listener_support_now()) ON CONFLICT(name) DO UPDATE SET last_success_at=EXCLUDED.last_success_at");
 }
}
